/* @lc app=leetcode id=971 lang=kotlin */ class Solution { fun f(n: TreeNode?, v: IntArray, i: IntArray, res: MutableList<Int>): Boolean = n == null || n.`val` == v[i[0]++] && (if (n.left?.let { it.`val` != v[i[0]] } == true) res.add(n.`val`) && f(n.right, v, i, res) && f(n.left, v, i, res) else f(n.left, v, i, res) && f(n.right, v, i, res)) fun flipMatchVoyage(root: TreeNode?, voyage: IntArray): List<Int> = IntArray(1).let { i -> mutableListOf<Int>().let { res -> if (f(root, voyage, i, res)) res else listOf(-1) } } }